(()=>{'use strict';const $=id=>document.getElementById(id),areas=['overview','social-campaigns','company-console','account-vault','digital-studio','storefront-editor','media-library','designer','catalogue','evidence','orders','launch','install','connections','partners','prospects','growth','my-work','my-studio','system-health','business-engine'];function metrics(){let s={designer:{},products:[],evidence:[],orders:[]};try{const v=JSON.parse(localStorage.getItem('zuxuru-fashion-service-v1'));if(v&&v.designer&&['products','evidence','orders'].every(k=>Array.isArray(v[k])))s=v;}catch{}$('dashboard-greeting').textContent=s.designer.name?s.designer.name+' · Business console':'My fashion business console.';$('dash-products').textContent=s.products.length;$('dash-evidence').textContent=s.evidence.length;$('dash-orders').textContent=s.orders.filter(o=>!['Delivered','Closed'].includes(o.stage)).length;$('dash-delivered').textContent=s.orders.filter(o=>o.stage==='Delivered').length;let next=!s.designer.name?['designer','Save your designer name, story and contact details.']:!s.products.length?['catalogue','Add your first design, sizes, availability and recorded costs.']:s.orders.some(o=>!['Delivered','Closed'].includes(o.stage))?['orders','Review your open customer enquiries and their next actions.']:['launch','Preview your storefront and prepare your launch caption.'];$('dash-next').textContent=next[1];$('dash-next-link').href='#'+next[0];}
function route(){const requested=location.hash.slice(1),current=areas.includes(requested)?requested:'overview';areas.forEach(id=>$(id).hidden=id!==current);document.querySelectorAll('.designer-sidebar nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+current;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});metrics();}
window.addEventListener('hashchange',route);document.addEventListener('submit',()=>setTimeout(metrics,0));document.addEventListener('change',()=>setTimeout(metrics,0));document.addEventListener('click',()=>setTimeout(metrics,0));window.addEventListener('storage',metrics);route();})();
